  // Hashed claimant IP (sha256 of ip+salt) — same hashing as CouponRedemption
  // (lib/coupon-order.ts hashIp). Null on the card-settle path / when the IP was
  // unavailable; NULLs are distinct so the unique below never collides on them.
  ipHash           String?
  // Which product flow granted it: VPS | HOSTING | EMAIL | GAME.
  serviceType      String
  // Ad campaign tag, from the /go/<slug>?c=<campaign> cookie. "" = organic.
  campaign         String    @default("")
