// Game patch-day and Rust wipe-day PLAYBOOKS (growth item mkt-026).
//
// Pure data + date maths only — no DB, no network — so it is unit-testable and
// importable from both the admin page and the worker sweep. The long-form
// playbook (who does what, how the agent-assisted drafting works, wording
// rules) lives in docs/PLAYBOOK-PATCH-DAY-AND-RUST-WIPE.md; this file is the
// machine-readable half: the checklist templates that become a WorkTask on the
// staff board, and the wipe calendar.
//
// NOTHING here sends anything to a customer. A checklist is an internal staff
// task; any customer-facing update or email stays a human-approved draft.

/** Rust force wipes: first Thursday of the month, ~19:00 UTC (see the playbook doc for the source). */
export const RUST_WIPE_HOUR_UTC = 19;

/** How far ahead of a wipe the 48-hour checklist is opened. */
export const RUST_WIPE_LEAD_HOURS = 48;

/** First Thursday of (year, month0) at RUST_WIPE_HOUR_UTC, as a UTC Date. */
export function rustForceWipeAt(year: number, month0: number): Date {
  const first = new Date(Date.UTC(year, month0, 1, RUST_WIPE_HOUR_UTC, 0, 0));
  const THURSDAY = 4;
  const offset = (THURSDAY - first.getUTCDay() + 7) % 7;
  return new Date(Date.UTC(year, month0, 1 + offset, RUST_WIPE_HOUR_UTC, 0, 0));
}

/** The next `count` force-wipe instants strictly after `from`. */
export function upcomingRustWipes(from: Date, count = 3): Date[] {
  const out: Date[] = [];
  let y = from.getUTCFullYear();
  let m = from.getUTCMonth();
  while (out.length < count) {
    const at = rustForceWipeAt(y, m);
    if (at.getTime() > from.getTime()) out.push(at);
    m += 1;
    if (m > 11) {
      m = 0;
      y += 1;
    }
  }
  return out;
}

/** Stable per-wipe key, e.g. "rust-wipe-2026-11-05" — used to dedupe the opened task. */
export function rustWipeKey(at: Date): string {
  return `rust-wipe-${at.toISOString().slice(0, 10)}`;
}

/** Stable per-patch key, e.g. "patch-valheim-2026-10-02". */
export function patchDayKey(family: string, day: Date): string {
  return `patch-${family.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${day.toISOString().slice(0, 10)}`;
}

/** Marker embedded in a generated task's description so the sweep can find it again. */
export function playbookMarker(key: string): string {
  return `[playbook:${key}]`;
}

export type PlaybookKind = "rust-wipe" | "patch-day";

export type ChecklistTemplate = { kind: PlaybookKind; title: (ctx: PlaybookCtx) => string; intro: (ctx: PlaybookCtx) => string; items: string[] };

export type PlaybookCtx = { key: string; family: string; label: string; at: Date | null };

const fmtUtc = (d: Date) =>
  d.toLocaleString("en-GB", { weekday: "short", day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "UTC" }) + " UTC";

export const RUST_WIPE_ITEMS: string[] = [
  "T-48h: confirm the wipe date and time against Facepunch's published schedule (it can move; do not trust this calendar alone).",
  "T-48h: list the Rust servers customers currently have (Admin > Servers, filter game = Rust) and note each one's auto-update setting and last backup time.",
  "T-48h: check fleet capacity on the nodes that host Rust (the monthly update and the map regeneration spike disk and CPU for a few minutes).",
  "T-48h: confirm the Rust game image still pulls the current client-compatible build (staging smoke test: start a throwaway server, check it reports the new build).",
  "T-48h: review the Rust wipe-day help article (/help) and the customer FAQ answers are still accurate; edit if the update changed anything customers can see.",
  "T-24h: draft the customer notice (in-portal announcement + optional email) in Admin > Announcements as a DRAFT only. A human approves and sends. No automated send.",
  "T-24h: make sure the Discord status channel and the status page have a maintenance note prepared (draft, not published).",
  "T-2h: take stock of open Rust support tickets; pin canned replies for the three expected questions (my server shows old build, map did not change, players cannot connect).",
  "T-0: watch the GAME_UPDATE jobs for Rust servers in Admin > Jobs; any failed or timed-out job is chased by hand, not retried blindly.",
  "T+1h: spot-check three real customer Rust servers (running, port reachable, new build reported). Record results on this task.",
  "T+24h: review tickets and Jobs for wipe-related failures; add anything new to the playbook doc and Admin > Docs.",
];

export const PATCH_DAY_ITEMS: string[] = [
  "Confirm the patch is real and what it changes (publisher patch notes, not a rumour). Paste the source link here.",
  "Decide impact: does it force a client update (servers must update before players can join) or is it optional?",
  "Check whether the family's image/update path is wired (docs: Game catalog + 'update source' table). If not, say so on the task; do not promise customers an automatic update.",
  "Check mods and plugins for this game: list installed mod frameworks and any known-incompatible versions before updating.",
  "Run the update on one internal/test server first and prove it with the update verifier's output, not just a clean exit code.",
  "Draft the same-day guide (what changed, what customers should do) as a draft blog/help article for human review.",
  "Draft the customer notice for people running that game (in-portal announcement or email) as a DRAFT. A human approves and sends. No automated send.",
  "After release: review Jobs for failed GAME_UPDATE runs on that game and tickets mentioning the patch.",
];

export const TEMPLATES: Record<PlaybookKind, ChecklistTemplate> = {
  "rust-wipe": {
    kind: "rust-wipe",
    title: (c) => `Rust force wipe: ${c.at ? fmtUtc(c.at) : c.key}`,
    intro: (c) =>
      `Rust monthly force wipe (first Thursday, about ${RUST_WIPE_HOUR_UTC}:00 UTC). Opened ${RUST_WIPE_LEAD_HOURS} hours ahead. Full playbook: docs/PLAYBOOK-PATCH-DAY-AND-RUST-WIPE.md. ${playbookMarker(c.key)}`,
    items: RUST_WIPE_ITEMS,
  },
  "patch-day": {
    kind: "patch-day",
    title: (c) => `Patch day: ${c.label}${c.at ? ` (${c.at.toISOString().slice(0, 10)})` : ""}`,
    intro: (c) =>
      `Game patch-day checklist for ${c.label}. Full playbook: docs/PLAYBOOK-PATCH-DAY-AND-RUST-WIPE.md. ${playbookMarker(c.key)}`,
    items: PATCH_DAY_ITEMS,
  },
};

/** True when `now` is inside the lead window of `wipeAt` (opens at wipeAt - lead, stays open until the wipe). */
export function wipeChecklistDue(now: Date, wipeAt: Date): boolean {
  const t = now.getTime();
  const start = wipeAt.getTime() - RUST_WIPE_LEAD_HOURS * 3_600_000;
  return t >= start && t < wipeAt.getTime();
}

