// DB half of the playbooks (mkt-026): turns a checklist template into a real
// WorkTask + WorkChecklistItem rows on the staff "Game operations" board.
// Shared by the admin page's manual buttons and worker/game-playbooks.ts, so
// both paths dedupe identically. Internal only: no customer-facing send here.

import { db } from "./db";
import { TEMPLATES, playbookMarker, type PlaybookCtx, type PlaybookKind } from "./game-playbooks";

export const PLAYBOOK_BOARD_NAME = "Game operations";
const COLUMNS = ["To do", "In progress", "Done"];

async function ensureBoard(createdById: string): Promise<{ boardId: string; todoColumnId: string }> {
  let board = await db.workBoard.findFirst({
    where: { name: PLAYBOOK_BOARD_NAME, archivedAt: null },
    include: { columns: { orderBy: { position: "asc" } } },
  });
  if (!board) {
    board = await db.workBoard.create({
      data: { name: PLAYBOOK_BOARD_NAME, description: "Patch-day and Rust wipe-day checklists (generated from lib/game-playbooks.ts).", createdById },
      include: { columns: true },
    });
    await db.workColumn.createMany({ data: COLUMNS.map((name, position) => ({ boardId: board!.id, name, position })) });
    board = await db.workBoard.findUniqueOrThrow({ where: { id: board.id }, include: { columns: { orderBy: { position: "asc" } } } });
  }
  const todo = board.columns[0];
  return { boardId: board.id, todoColumnId: todo.id };
}

/** True when a task carrying this playbook key already exists (open, done or archived). */
export async function playbookTaskExists(key: string): Promise<boolean> {
  const hit = await db.workTask.findFirst({ where: { description: { contains: playbookMarker(key) } }, select: { id: true } });
  return !!hit;
}

export type OpenResult = { created: boolean; taskId: string | null };

/**
 * Create the checklist task for `kind`/`ctx` unless one with the same key
 * already exists. Idempotent: a second call (or a worker restart) is a no-op.
