// Rust wipe-day checklist sweep (growth item mkt-026).
//
// Opens the 48-hour Rust force-wipe checklist as a WorkTask on the staff
// "Game operations" board and pings the admins (internal Notification via
// notifyAdmins). INTERNAL ONLY: this never emails, posts or messages a
// customer. Patch-day checklists are opened by hand from /admin/playbooks (a
// human decides a patch matters), so this sweep only handles the wipe calendar.
//
// GATED behind `game_playbooks_enabled` (default OFF; env GAME_PLAYBOOKS_ENABLED
// also enables it). While off this returns before reading anything.

import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { upcomingRustWipes, wipeChecklistDue, rustWipeKey } from "../lib/game-playbooks";
import { openPlaybookTask } from "../lib/game-playbooks-tasks";
import { notifyAdmins } from "./monitor";

export async function gamePlaybooksSweep(now: Date = new Date()): Promise<void> {
  // ===== MASTER KILL-SWITCH (first line) =====
  const envOn = process.env.GAME_PLAYBOOKS_ENABLED === "true";
  if (!envOn && !(await getSettingBool("game_playbooks_enabled", false))) return;

  const admin = await db.user.findFirst({ where: { role: "ADMIN" }, orderBy: { createdAt: "asc" }, select: { id: true } });
  if (!admin) return;

  for (const at of upcomingRustWipes(now, 2)) {
    if (!wipeChecklistDue(now, at)) continue;
    const key = rustWipeKey(at);
    const res = await openPlaybookTask("rust-wipe", { key, family: "rust", label: "Rust force wipe", at }, admin.id);
    if (res.created) {
      await notifyAdmins(
        `Rust force wipe in under 48 hours (${at.toISOString().slice(0, 10)})`,
        "The wipe-day checklist is open on the Game operations board.",
        "/admin/playbooks",
      );
      console.log(`[playbooks] opened ${key}`);
    }
  }
}
