// School club, clan and LAN programme (growth item mkt-041): pure rules.
//
// No DB, no network. The offer itself is deliberately NOT here: this module
// decides who may APPLY and gives the reviewer a hint about the email domain.
// Every discount value comes from the existing Coupons engine, issued by a
// human (see docs/PROGRAMME-CLUBS-CLANS-LAN.md and its "Owner decisions").

export const CLUB_KINDS = ["SCHOOL_CLUB", "CLAN", "LAN_EVENT"] as const;
export type ClubKind = (typeof CLUB_KINDS)[number];

export const CLUB_KIND_LABEL: Record<ClubKind, string> = {
  SCHOOL_CLUB: "School or university club",
  CLAN: "Clan or community team",
  LAN_EVENT: "LAN or esports event",
};

export const CLUB_STATUSES = ["PENDING", "NEEDS_INFO", "APPROVED", "REJECTED", "WITHDRAWN"] as const;
export type ClubStatus = (typeof CLUB_STATUSES)[number];

/** The time-boxed test runs in these regions first (item mkt-041). Others are still queued, flagged. */
export const PILOT_COUNTRIES = ["SG", "PH", "MY"] as const;

/** Proposed, owner-editable eligibility thresholds (NOT money). */
export const MIN_MEMBERS = 5;
export const MAX_MEMBERS = 5000;
export const LAN_MIN_LEAD_DAYS = 7;
export const LAN_MAX_LEAD_DAYS = 180;
export const LAN_MAX_DURATION_DAYS = 14;

/** Free webmail providers: never accepted as proof of a school or institution. */
const PUBLIC_MAIL = new Set([
  "gmail.com", "googlemail.com", "yahoo.com", "ymail.com", "outlook.com", "hotmail.com", "live.com", "msn.com",
  "icloud.com", "me.com", "proton.me", "protonmail.com", "aol.com", "gmx.com", "mail.com", "zoho.com", "yandex.com",
]);

// Education-style hostnames: x.edu, x.edu.sg, x.ac.uk, x.sch.id, school.* ...
const INSTITUTION_LABELS = new Set(["edu", "ac", "sch", "school", "k12"]);

export function emailDomain(email: string): string {
  const at = String(email ?? "").trim().toLowerCase().lastIndexOf("@");
  return at < 0 ? "" : String(email).trim().toLowerCase().slice(at + 1);
}

/** institutional | public | other. A HINT for the human reviewer only; never treated as proof. */
export function classifyEmailDomain(domain: string): "institutional" | "public" | "other" {
  const d = domain.trim().toLowerCase();
  if (!d) return "other";
  if (PUBLIC_MAIL.has(d)) return "public";
  const labels = d.split(".");
  if (labels.slice(1).some((l) => INSTITUTION_LABELS.has(l)) || labels[0] === "school") return "institutional";
  return "other";
}

export type ClubInput = {
  kind: string;
  orgName: string;
  contactName: string;
  contactEmail: string;
  contactRole: string;
  institutionName: string;
  country: string;
  memberCount: number | null;
  game: string;
  usage: string;
  eventStart: Date | null;
  eventEnd: Date | null;
  website: string;
};

export type EligibilityResult = { ok: true; warnings: string[] } | { ok: false; error: string };

/** Hard rules for accepting an application into the queue. Approval stays human. */
export function checkEligibility(i: ClubInput, now: Date = new Date()): EligibilityResult {
  const warnings: string[] = [];
  if (!(CLUB_KINDS as readonly string[]).includes(i.kind)) return { ok: false, error: "Choose what kind of group this is." };
  const kind = i.kind as ClubKind;
  const dom = emailDomain(i.contactEmail);
  const cls = classifyEmailDomain(dom);

  if (kind === "SCHOOL_CLUB") {
    if (!i.institutionName.trim()) return { ok: false, error: "Tell us which school or university the club belongs to." };
    if (cls === "public") return { ok: false, error: "School clubs apply with a staff or school email address, not a free webmail address. If your school has no email domain, use the Clan option and tell us about the club." };
    if (cls === "other") warnings.push("Email domain does not look institutional: verify against the school's own website.");
  }
  if (kind === "CLAN") {
    if (i.memberCount === null || i.memberCount < MIN_MEMBERS) return { ok: false, error: `A clan or community team needs at least ${MIN_MEMBERS} members to apply.` };
  }
  if (kind === "LAN_EVENT") {
    if (!i.institutionName.trim()) return { ok: false, error: "Tell us the venue or organising institution." };
    if (!i.eventStart || !i.eventEnd) return { ok: false, error: "Enter the event start and end dates." };
    const lead = (i.eventStart.getTime() - now.getTime()) / 86_400_000;
    if (lead < LAN_MIN_LEAD_DAYS) return { ok: false, error: `Applications close ${LAN_MIN_LEAD_DAYS} days before the event starts.` };
    if (lead > LAN_MAX_LEAD_DAYS) return { ok: false, error: `Applications open ${LAN_MAX_LEAD_DAYS} days before the event; please apply closer to the date.` };
    const dur = (i.eventEnd.getTime() - i.eventStart.getTime()) / 86_400_000;
    if (dur < 0) return { ok: false, error: "The event cannot end before it starts." };
    if (dur > LAN_MAX_DURATION_DAYS) return { ok: false, error: `Events longer than ${LAN_MAX_DURATION_DAYS} days are handled as a custom enquiry; please contact us.` };
  }
  if (i.memberCount !== null && (i.memberCount < 1 || i.memberCount > MAX_MEMBERS)) return { ok: false, error: "Enter a realistic member count." };
  if (i.country && !(PILOT_COUNTRIES as readonly string[]).includes(i.country)) warnings.push("Outside the pilot regions (SG, PH, MY): queue only.");
  return { ok: true, warnings };
}
