export type ClubResult = { ok: boolean; message: string };

const text = (max: number) => z.string().trim().max(max);

const schema = z.object({
  kind: z.enum(CLUB_KINDS),
  orgName: text(120).min(2, "Enter the name of your group."),
  contactName: text(120).min(1, "Enter your name."),
  contactEmail: z.email("That does not look like a valid email.").max(200),
  contactRole: text(80),
  institutionName: text(160),
  country: z.string().trim().toUpperCase().regex(/^[A-Z]{2}$/, "Choose your country."),
  memberCount: z.number().int().nullable(),
  game: text(80),
  usage: text(1500).min(20, "Tell us a little about how you would use the server (at least 20 characters)."),
  eventStart: z.date().nullable(),
  eventEnd: z.date().nullable(),
  website: text(200).refine((v) => v === "" || /^https?:\/\//i.test(v), "Website must start with http:// or https://"),
});

export type ClubFormInput = {
  kind: string;
  orgName: string;
  contactName: string;
  contactEmail: string;
  contactRole?: string;
  institutionName?: string;
  country: string;
  memberCount?: string | number | null;
  game?: string;
  usage: string;
  eventStart?: string;
  eventEnd?: string;
  website?: string;
  /** honeypot */
  company?: string;
};

function parseDate(v: string | undefined): Date | null {
  if (!v) return null;
  const d = new Date(`${v}T00:00:00.000Z`);
  return Number.isNaN(d.getTime()) ? null : d;
}

export async function submitClubApplication(input: ClubFormInput): Promise<ClubResult> {
  if (!(await getSettingBool("club_programme_enabled", false))) {
    return { ok: false, message: "This programme is not open yet." };
  }
  // Honeypot tripped: pretend success, store nothing.
  if (typeof input?.company === "string" && input.company.trim()) {
    return { ok: true, message: "Thanks, your application is in." };
  }

  let ip = "";
  try {
    ip = clientIp(await headers());
  } catch {
    ip = "";
  }
  const rl = checkRateLimit(`club-apply:${ip || "unknown"}`, { max: 5, windowMs: 10 * 60_000 });
  if (!rl.ok) return { ok: false, message: "Several applications were sent from your connection. Please wait a few minutes and try again." };

  const mc = input?.memberCount === "" || input?.memberCount == null ? null : Number(input.memberCount);
  const parsed = schema.safeParse({
    kind: input?.kind,
    orgName: input?.orgName,
    contactName: input?.contactName,
    contactEmail: typeof input?.contactEmail === "string" ? input.contactEmail.trim().toLowerCase() : input?.contactEmail,
    contactRole: input?.contactRole ?? "",
    institutionName: input?.institutionName ?? "",
    country: input?.country,
    memberCount: mc !== null && Number.isFinite(mc) ? Math.trunc(mc) : null,
    game: input?.game ?? "",
    usage: input?.usage,
    eventStart: parseDate(input?.eventStart),
    eventEnd: parseDate(input?.eventEnd),
    website: input?.website ?? "",
  });
  if (!parsed.success) return { ok: false, message: parsed.error.issues[0]?.message ?? "Please check the form and try again." };
  const d = parsed.data;

  const elig = checkEligibility(d satisfies ClubInput);
  if (!elig.ok) return { ok: false, message: elig.error };

  // One open application per email + kind: prevents queue flooding, tells a real applicant honestly.
  const open = await db.clubApplication.count({
    where: { contactEmail: d.contactEmail, kind: d.kind, status: { in: ["PENDING", "NEEDS_INFO"] } },
  });
  if (open > 0) return { ok: true, message: "We already have an open application from this email for this type of group. We will reply there." };

  const dom = emailDomain(d.contactEmail);
  const app = await db.clubApplication.create({
    data: {
      kind: d.kind,
      orgName: d.orgName,
      contactName: d.contactName,
      contactEmail: d.contactEmail,
      contactRole: d.contactRole,
      institutionName: d.institutionName,
      emailDomain: dom,
      emailDomainClass: classifyEmailDomain(dom),
      country: d.country,
      memberCount: d.memberCount,
      game: d.game,
      usage: d.usage,
      eventStart: d.eventStart,
      eventEnd: d.eventEnd,
      website: d.website,
      reviewNote: elig.warnings.join(" "),
    },
  });

  // Internal admin ping only (same pattern as ticket notifications). No customer-facing send.
  try {
    const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
    if (admins.length) {
      await db.notification.createMany({
        data: admins.map((a) => ({ userId: a.id, title: `Club application: ${d.orgName}`, href: `/admin/club-applications#${app.id}` })),
      });
    }
  } catch (e) {
    console.error("[club] admin notify failed (non-fatal)", e);
  }
  return { ok: true, message: "Thanks, your application is in. A person reviews every application and will reply by email." };
}

const reviewSchema = z.object({
  id: z.string().min(1),
  status: z.enum(CLUB_STATUSES),
  note: text(1000),
  couponCode: text(60),
});

/** Admin: set the review outcome. Records the coupon code an admin issued separately; creates/grants nothing. */
export async function adminReviewClubApplication(formData: FormData): Promise<void> {
  const admin = await requireArea("platform");
  const parsed = reviewSchema.safeParse({
    id: formData.get("id"),
    status: formData.get("status"),
    note: String(formData.get("note") ?? ""),
    couponCode: String(formData.get("couponCode") ?? "").toUpperCase(),
  });
  if (!parsed.success) return;
  const { id, status, note, couponCode } = parsed.data;
  const row = await db.clubApplication.findUnique({ where: { id }, select: { id: true, orgName: true } });
  if (!row) return;
  await db.clubApplication.update({
    where: { id },
    data: { status, reviewNote: note, couponCode, reviewedById: admin.id, reviewedAt: new Date() },
  });
  await db.auditLog.create({ data: { userId: admin.id, action: "admin.club_application_review", detail: `${row.orgName} -> ${status}` } });
  revalidatePath("/admin/club-applications");
}
