"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { GAME_FAMILIES, GAME_DISPLAY, type GameFamily } from "./games";
import { patchDayKey, rustWipeKey, upcomingRustWipes } from "./game-playbooks";
import { openPlaybookTask } from "./game-playbooks-tasks";

/** Admin: open the checklist for the next Rust force wipe now (idempotent). INTERNAL task only. */
export async function openNextRustWipeChecklist(): Promise<void> {
  const admin = await requireArea("platform");
  const at = upcomingRustWipes(new Date(), 1)[0];
  const key = rustWipeKey(at);
  const res = await openPlaybookTask("rust-wipe", { key, family: "rust", label: "Rust force wipe", at }, admin.id);
  if (res.created) await db.auditLog.create({ data: { userId: admin.id, action: "admin.playbook_open", detail: key } });
  revalidatePath("/admin/playbooks");
}

/** Admin: open a patch-day checklist for one game family (once per family per UTC day). INTERNAL task only. */
export async function openPatchDayChecklist(formData: FormData): Promise<void> {
  const admin = await requireArea("platform");
  const family = String(formData.get("family") ?? "");
  if (!(GAME_FAMILIES as readonly string[]).includes(family)) return;
  const day = new Date();
  const key = patchDayKey(family, day);
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
  const res = await openPlaybookTask("patch-day", { key, family, label, at: day }, admin.id);
  if (res.created) await db.auditLog.create({ data: { userId: admin.id, action: "admin.playbook_open", detail: key } });
  revalidatePath("/admin/playbooks");
}
