                    <Badge tone="amber">Due now</Badge>
                  ) : (
                    <Badge tone="slate">Not opened</Badge>
                  )}
                </span>
              </li>
            );
          })}
        </ul>
        <form action={openNextRustWipeChecklist} className="mt-4">
          <button type="submit" className="btn-primary px-4 py-2 text-sm">Open the next wipe checklist now</button>
        </form>
      </div>

      <div className="card">
        <p className="section-label mb-3">Patch day</p>
        <p className="mb-4 text-sm text-slate-400">
          A person decides a patch matters, then opens its checklist. Once per game per UTC day; repeats are ignored.
        </p>
        <form action={openPatchDayChecklist} className="flex flex-wrap items-end gap-3">
          <label className="text-sm">
            <span className="mb-1 block text-slate-400">Game</span>
            <select name="family" className="input" defaultValue="rust">
              {GAME_FAMILIES.map((f) => (
                <option key={f} value={f}>{GAME_DISPLAY[f].name}</option>
              ))}
            </select>
          </label>
          <button type="submit" className="btn-primary px-4 py-2 text-sm">Open patch-day checklist</button>
        </form>
      </div>

      <div className="card">
        <p className="section-label mb-3">Recent playbook tasks</p>
        {recent.length === 0 ? (
          <p className="text-sm text-slate-400">None yet. They appear on the &ldquo;{PLAYBOOK_BOARD_NAME}&rdquo; board in <Link className="text-brand-300 hover:underline" href="/admin/tasks">Tasks</Link>.</p>
        ) : (
          <ul className="space-y-1.5 text-sm">
            {recent.map((t) => (
              <li key={t.id}>
                <Link className="text-brand-300 hover:underline" href={`/admin/tasks?board=${t.boardId}&task=${t.id}`}>{t.title}</Link>
                <span className="ml-2 text-slate-500">{t.completedAt ? "done" : "open"}</span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
