import { CLUB_KIND_LABEL, CLUB_STATUSES, type ClubKind } from "@/lib/club-programme";
import { adminReviewClubApplication } from "@/lib/actions-club";

export const dynamic = "force-dynamic";

const TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = {
  PENDING: "amber",
  NEEDS_INFO: "brand",
  APPROVED: "green",
  REJECTED: "red",
  WITHDRAWN: "slate",
};

export default async function AdminClubApplications() {
  await requireArea("platform");
  const [on, rows, pending] = await Promise.all([
    getSettingBool("club_programme_enabled", false),
    db.clubApplication.findMany({ orderBy: { createdAt: "desc" }, take: 200 }),
    db.clubApplication.count({ where: { status: { in: ["PENDING", "NEEDS_INFO"] } } }),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Club applications"
        sub="School club, clan and LAN programme. Review by hand; nothing is emailed or discounted automatically."
      >
        <Badge tone={on ? "green" : "slate"}>{on ? "Programme live" : "Programme off"}</Badge>
        <Badge tone="amber">{pending} to review</Badge>
      </PageHeader>

      <div className="card text-sm text-slate-400">
        To approve: verify the group (the email-domain hint is not proof), create the discount in{" "}
        <a className="text-brand-300 hover:underline" href="/admin/coupons">Coupons</a> using the values the owner chose, paste the code below, reply to the contact yourself, then save.
      </div>

      {rows.length === 0 ? (
        <div className="card text-sm text-slate-400">No applications yet.</div>
      ) : (
        rows.map((r) => (
          <div key={r.id} id={r.id} className="card space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <p className="font-semibold">{r.orgName} <span className="font-normal text-slate-400">· {CLUB_KIND_LABEL[r.kind as ClubKind] ?? r.kind}</span></p>
              <span className="flex items-center gap-2">
                <Badge tone={TONE[r.status] ?? "slate"}>{r.status}</Badge>
                <span className="text-xs text-slate-500">{timeAgo(r.createdAt)}</span>
              </span>
            </div>
            <dl className="grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2">
              <div><dt className="inline text-slate-500">Contact: </dt><dd className="inline">{r.contactName}{r.contactRole ? ` (${r.contactRole})` : ""}, <a className="text-brand-300 hover:underline" href={`mailto:${r.contactEmail}`}>{r.contactEmail}</a></dd></div>
              <div><dt className="inline text-slate-500">Email domain: </dt><dd className="inline">{r.emailDomain} <Badge tone={r.emailDomainClass === "institutional" ? "green" : r.emailDomainClass === "public" ? "red" : "slate"}>{r.emailDomainClass}</Badge></dd></div>
              <div><dt className="inline text-slate-500">Institution / venue: </dt><dd className="inline">{r.institutionName || "n/a"}</dd></div>
              <div><dt className="inline text-slate-500">Country: </dt><dd className="inline">{r.country || "n/a"}</dd></div>
              <div><dt className="inline text-slate-500">Members: </dt><dd className="inline">{r.memberCount ?? "n/a"}</dd></div>
              <div><dt className="inline text-slate-500">Game: </dt><dd className="inline">{r.game || "n/a"}</dd></div>
              {r.eventStart && r.eventEnd ? (
                <div><dt className="inline text-slate-500">Event: </dt><dd className="inline">{r.eventStart.toISOString().slice(0, 10)} to {r.eventEnd.toISOString().slice(0, 10)}</dd></div>
              ) : null}
              {r.website ? <div><dt className="inline text-slate-500">Website: </dt><dd className="inline break-all">{r.website}</dd></div> : null}
            </dl>
            <p className="whitespace-pre-wrap rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm text-slate-300">{r.usage}</p>
            <form action={adminReviewClubApplication} className="grid gap-3 sm:grid-cols-[10rem_1fr_12rem_auto] sm:items-end">
              <input type="hidden" name="id" value={r.id} />
              <label className="text-sm"><span className="mb-1 block text-slate-400">Status</span>
                <select name="status" className="input" defaultValue={r.status}>{CLUB_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}</select>
              </label>
              <label className="text-sm"><span className="mb-1 block text-slate-400">Internal note</span>
                <input name="note" className="input" defaultValue={r.reviewNote} maxLength={1000} />
              </label>
              <label className="text-sm"><span className="mb-1 block text-slate-400">Coupon code issued</span>
                <input name="couponCode" className="input font-mono" defaultValue={r.couponCode} maxLength={60} />
              </label>
              <button type="submit" className="btn-primary px-4 py-2 text-sm">Save</button>
            </form>
          </div>
        ))
      )}
    </div>
  );
}
