import { ClubApplyForm } from "@/components/marketing/ClubApplyForm";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Clubs, Clans & LAN Events",
  description:
    "Running a school club, a clan or a LAN event? Apply for a game server arrangement for your group. Every application is reviewed by a person.",
  alternates: { canonical: "/clubs" },
};

const GROUPS = [
  { icon: <IconUsers />, title: "School and university clubs", body: "Esports, game-dev and computing clubs. Apply with a staff or school email address and we confirm the club with your institution." },
  { icon: <IconChat />, title: "Clans and community teams", body: `A team of at least ${MIN_MEMBERS} people who play together on a regular server and want a home for it.` },
  { icon: <IconGlobe />, title: "LAN and esports events", body: `One-off or weekend events. Apply at least ${LAN_MIN_LEAD_DAYS} days before the start date so there is time to set things up.` },
];

const RULES = [
  "A person reviews every application. There is no automatic approval.",
  "We confirm schools and venues independently, so a free webmail address is not accepted for a school club.",
  "The arrangement for approved groups is confirmed to you in writing before anything is set up. Nothing is charged or discounted by submitting this form.",
  "Approved groups get a discount code for members to use through the normal checkout; the details are in your reply.",
  "We are starting with a small test in Singapore, the Philippines and Malaysia. Groups elsewhere can still apply and will be queued.",
];

export default async function ClubsPage() {
  if (!(await getSettingBool("club_programme_enabled", false))) notFound();
  return (
    <>
      <PageHero
        eyebrow="Clubs, clans & LAN events"
        title="A server for the group,"
        highlight="not just one player"
        sub="Tell us about your club, clan or event. We read every application and reply by email with what we can offer your group."
        primary={{ label: "Apply now", href: "#apply" }}
        secondary={{ label: "See the rules", href: "#rules" }}
      />

      <Section tone="panel" size="lg">
        <SectionTitle eyebrow="Who can apply" title="Three kinds of group" sub="Pick the one that fits. If you are not sure, apply as a clan and explain in the notes." />
        <div className="mt-12 grid gap-5 sm:grid-cols-3">
          {GROUPS.map((g, i) => (
            <FeatureCard key={g.title} icon={g.icon} title={g.title} delay={i * 60}>{g.body}</FeatureCard>
          ))}
        </div>
      </Section>

      <Section size="lg" id="rules">
        <SectionTitle eyebrow="How it works" title="The rules, plainly" />
        <ul className="mx-auto mt-10 max-w-2xl space-y-3">
          {RULES.map((t) => (
            <li key={t} className="flex items-start gap-2.5 text-sm text-slate-300">
              <span className="mt-0.5 flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={12} /></span>
              {t}
            </li>
          ))}
        </ul>
      </Section>

      <Section tone="panel" size="lg" id="apply">
        <SectionTitle eyebrow="Apply" title="Tell us about your group" />
        <div className="mx-auto mt-10 max-w-2xl"><ClubApplyForm /></div>
      </Section>
    </>
  );
}
