"use client";

import { useState, useTransition } from "react";
import { submitClubApplication, type ClubFormInput } from "@/lib/actions-club";
import { CLUB_KINDS, CLUB_KIND_LABEL, type ClubKind } from "@/lib/club-programme";

const COUNTRIES: [string, string][] = [
  ["SG", "Singapore"], ["PH", "Philippines"], ["MY", "Malaysia"], ["ID", "Indonesia"], ["VN", "Vietnam"], ["TH", "Thailand"],
  ["AU", "Australia"], ["IN", "India"], ["CA", "Canada"], ["US", "United States"], ["GB", "United Kingdom"], ["OT", "Other"],
];

const field = "input w-full";

export function ClubApplyForm() {
  const [kind, setKind] = useState<ClubKind>("SCHOOL_CLUB");
  const [pending, start] = useTransition();
  const [result, setResult] = useState<{ ok: boolean; message: string } | null>(null);

  function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const g = (k: string) => String(fd.get(k) ?? "");
    const input: ClubFormInput = {
      kind,
      orgName: g("orgName"),
      contactName: g("contactName"),
      contactEmail: g("contactEmail"),
      contactRole: g("contactRole"),
      institutionName: g("institutionName"),
      country: g("country"),
      memberCount: g("memberCount"),
      game: g("game"),
      usage: g("usage"),
      eventStart: g("eventStart"),
      eventEnd: g("eventEnd"),
      website: g("website"),
      company: g("company"),
    };
    start(async () => {
      try {
        setResult(await submitClubApplication(input));
      } catch {
        setResult({ ok: false, message: "Something went wrong sending that. Please try again." });
      }
    });
  }

  if (result?.ok) {
    return <div className="card text-center text-sm text-slate-200" role="status">{result.message}</div>;
  }

  const lan = kind === "LAN_EVENT";
  return (
    <form onSubmit={onSubmit} className="card space-y-4" noValidate>
      <fieldset className="grid gap-2 sm:grid-cols-3">
        <legend className="mb-1 text-sm text-slate-400">What kind of group?</legend>
        {CLUB_KINDS.map((k) => (
          <label key={k} className={`cursor-pointer rounded-xl border px-3 py-2 text-sm ${kind === k ? "border-brand-500/60 bg-brand-500/10 text-white" : "border-white/[0.08] text-slate-300"}`}>
            <input type="radio" name="kind" value={k} checked={kind === k} onChange={() => setKind(k)} className="sr-only" />
            {CLUB_KIND_LABEL[k]}
          </label>
        ))}
      </fieldset>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="text-sm"><span className="mb-1 block text-slate-400">Group name</span><input name="orgName" className={field} maxLength={120} required /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">{kind === "CLAN" ? "Community or server name (optional)" : "School, university or venue"}</span><input name="institutionName" className={field} maxLength={160} required={kind !== "CLAN"} /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">Your name</span><input name="contactName" className={field} maxLength={120} required /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">Your role</span><input name="contactRole" className={field} maxLength={80} placeholder="Teacher, club president, organiser" /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">{kind === "SCHOOL_CLUB" ? "Staff or school email" : "Email"}</span><input name="contactEmail" type="email" className={field} maxLength={200} required /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">Country</span>
          <select name="country" className={field} defaultValue="SG" required>{COUNTRIES.map(([c, n]) => <option key={c} value={c}>{n}</option>)}</select>
        </label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">Number of members</span><input name="memberCount" type="number" min={1} className={field} /></label>
        <label className="text-sm"><span className="mb-1 block text-slate-400">Game</span><input name="game" className={field} maxLength={80} placeholder="Minecraft, Valheim, CS2..." /></label>
        {lan ? (
          <>
            <label className="text-sm"><span className="mb-1 block text-slate-400">Event starts</span><input name="eventStart" type="date" className={field} required /></label>
            <label className="text-sm"><span className="mb-1 block text-slate-400">Event ends</span><input name="eventEnd" type="date" className={field} required /></label>
          </>
        ) : null}
      </div>

      <label className="block text-sm"><span className="mb-1 block text-slate-400">Website or social page (optional)</span><input name="website" className={field} maxLength={200} placeholder="https://" /></label>
      <label className="block text-sm"><span className="mb-1 block text-slate-400">How would you use the server?</span><textarea name="usage" className={`${field} min-h-[110px]`} maxLength={1500} required /></label>

      {/* Honeypot: hidden from people, irresistible to bots. */}
      <div aria-hidden="true" className="absolute left-[-9999px] h-0 w-0 overflow-hidden"><label>Company<input name="company" tabIndex={-1} autoComplete="off" /></label></div>

      {result && !result.ok ? <p className="text-sm text-red-400" role="alert">{result.message}</p> : null}
      <button type="submit" disabled={pending} className="btn-primary px-6 py-3 text-base disabled:opacity-60">{pending ? "Sending..." : "Send application"}</button>
      <p className="text-xs text-slate-500">Submitting does not charge you or commit either side. We only use these details to review your application.</p>
    </form>
  );
}
