import {
  rustForceWipeAt, upcomingRustWipes, rustWipeKey, patchDayKey, wipeChecklistDue,
  RUST_WIPE_ITEMS, PATCH_DAY_ITEMS, TEMPLATES, playbookMarker,
} from "../lib/game-playbooks";

test("rust force wipe is the first Thursday at 19:00 UTC (dates named in the growth brief)", () => {
  assert.equal(rustForceWipeAt(2026, 10).toISOString(), "2026-11-05T19:00:00.000Z");
  assert.equal(rustForceWipeAt(2026, 11).toISOString(), "2026-12-03T19:00:00.000Z");
});

test("first Thursday holds when the 1st is itself a Thursday and when it is a Friday", () => {
  assert.equal(rustForceWipeAt(2026, 9).toISOString(), "2026-10-01T19:00:00.000Z"); // 1 Oct 2026 is a Thursday
  assert.equal(rustForceWipeAt(2026, 7).toISOString(), "2026-08-06T19:00:00.000Z"); // 1 Aug 2026 is a Saturday
  for (let m = 0; m < 12; m++) assert.equal(rustForceWipeAt(2027, m).getUTCDay(), 4);
});

test("upcoming wipes are strictly in the future, in order, and roll over the year", () => {
  const from = new Date("2026-11-05T19:00:00.000Z"); // exactly at a wipe: that one is not upcoming
  const u = upcomingRustWipes(from, 3).map((d) => d.toISOString().slice(0, 10));
  assert.deepEqual(u, ["2026-12-03", "2027-01-07", "2027-02-04"]);
});

test("checklist opens 48h before and closes at the wipe", () => {
  const wipe = new Date("2026-11-05T19:00:00.000Z");
  assert.equal(wipeChecklistDue(new Date("2026-11-03T18:59:59.000Z"), wipe), false);
  assert.equal(wipeChecklistDue(new Date("2026-11-03T19:00:00.000Z"), wipe), true);
  assert.equal(wipeChecklistDue(new Date("2026-11-05T18:59:59.000Z"), wipe), true);
  assert.equal(wipeChecklistDue(wipe, wipe), false);
});

test("dedupe keys are stable and filesystem/url safe", () => {
  assert.equal(rustWipeKey(new Date("2026-11-05T19:00:00.000Z")), "rust-wipe-2026-11-05");
  assert.equal(patchDayKey("Project Zomboid", new Date("2026-10-02T05:00:00.000Z")), "patch-project-zomboid-2026-10-02");
  assert.equal(playbookMarker("k"), "[playbook:k]");
});

test("every checklist item fits the WorkChecklistItem label cap (200) without truncation", () => {
  for (const item of [...RUST_WIPE_ITEMS, ...PATCH_DAY_ITEMS]) assert.ok(item.length <= 200, `too long (${item.length}): ${item}`);
});

test("templates carry the marker the sweep dedupes on, and never promise an automated customer send", () => {
  const ctx = { key: "rust-wipe-2026-11-05", family: "rust", label: "Rust force wipe", at: new Date("2026-11-05T19:00:00.000Z") };
  assert.ok(TEMPLATES["rust-wipe"].intro(ctx).includes(playbookMarker(ctx.key)));
  const all = [...RUST_WIPE_ITEMS, ...PATCH_DAY_ITEMS].join("\n");
  assert.match(all, /No automated send/);
  assert.doesNotMatch(all, /provider/i);
});

test("worker sweep is gated off by default and only touches internal tables", () => {
  const src = readFileSync(new URL("../worker/game-playbooks.ts", import.meta.url), "utf8");
  assert.match(src, /game_playbooks_enabled", false/);
  assert.doesNotMatch(src, /sendMail|postChannelMessage|sendSms/);
  const tasks = readFileSync(new URL("../lib/game-playbooks-tasks.ts", import.meta.url), "utf8");
  assert.doesNotMatch(tasks, /sendMail|postChannelMessage|sendSms/);
});
