  usage: "Weekly club sessions", eventStart: null, eventEnd: null, website: "",
};

test("email domain helpers", () => {
  assert.equal(emailDomain("Foo@Bar.EDU.sg "), "bar.edu.sg");
  assert.equal(emailDomain("nope"), "");
  assert.equal(classifyEmailDomain("gmail.com"), "public");
  assert.equal(classifyEmailDomain("nus.edu.sg"), "institutional");
  assert.equal(classifyEmailDomain("um.edu.my"), "institutional");
  assert.equal(classifyEmailDomain("ateneo.edu"), "institutional");
  assert.equal(classifyEmailDomain("school.example.com"), "institutional");
  assert.equal(classifyEmailDomain("example.com"), "other");
  assert.equal(classifyEmailDomain(""), "other");
});

