  assert.equal(checkEligibility(base, NOW).ok, true);
  assert.equal(checkEligibility({ ...base, institutionName: "" }, NOW).ok, false);
  assert.equal(checkEligibility({ ...base, contactEmail: "t@gmail.com" }, NOW).ok, false);
  const other = checkEligibility({ ...base, contactEmail: "t@example.com" }, NOW);
  assert.equal(other.ok, true);
  if (other.ok) assert.ok(other.warnings.some((w) => /institutional/.test(w)));
});

test("clan: minimum members", () => {
  const clan = { ...base, kind: "CLAN", contactEmail: "x@gmail.com", institutionName: "" };
  assert.equal(checkEligibility({ ...clan, memberCount: 4 }, NOW).ok, false);
  assert.equal(checkEligibility({ ...clan, memberCount: null }, NOW).ok, false);
  assert.equal(checkEligibility({ ...clan, memberCount: 5 }, NOW).ok, true);
});

test("LAN event: date window and duration", () => {
  const lan = { ...base, kind: "LAN_EVENT", contactEmail: "o@gmail.com" };
  const d = (s: string) => new Date(s + "T00:00:00.000Z");
  assert.equal(checkEligibility({ ...lan, eventStart: null, eventEnd: null }, NOW).ok, false);
  assert.equal(checkEligibility({ ...lan, eventStart: d("2026-10-05"), eventEnd: d("2026-10-06") }, NOW).ok, false); // too soon
  assert.equal(checkEligibility({ ...lan, eventStart: d("2026-10-20"), eventEnd: d("2026-10-21") }, NOW).ok, true);
  assert.equal(checkEligibility({ ...lan, eventStart: d("2026-10-20"), eventEnd: d("2026-10-19") }, NOW).ok, false);
  assert.equal(checkEligibility({ ...lan, eventStart: d("2026-10-20"), eventEnd: d("2026-11-20") }, NOW).ok, false); // too long
  assert.equal(checkEligibility({ ...lan, eventStart: d("2027-06-01"), eventEnd: d("2027-06-02") }, NOW).ok, false); // too far
});

test("unknown kind and pilot-region flag", () => {
  assert.equal(checkEligibility({ ...base, kind: "BOGUS" }, NOW).ok, false);
  const r = checkEligibility({ ...base, country: "US" }, NOW);
  assert.equal(r.ok, true);
  if (r.ok) assert.ok(r.warnings.some((w) => /pilot/i.test(w)));
});

test("programme never creates a coupon, charges or sends mail automatically", () => {
  const src = readFileSync(new URL("../lib/actions-club.ts", import.meta.url), "utf8");
  assert.doesNotMatch(src, /db\.coupon\.|sendMail|stripe|walletTransaction|postChannelMessage/i);
  assert.match(src, /club_programme_enabled", false/);
  const page = readFileSync(new URL("../app/(marketing)/clubs/page.tsx", import.meta.url), "utf8");
  assert.match(page, /notFound\(\)/);
  assert.doesNotMatch(page, /\$\d|\d+% off|provider/i);
});
